#[derive(Clone, Debug, Default, PartialEq)]
pub struct WireRecord {
    pub kind: WireRecordKind,
    pub id: f64,
    pub generation: f64,
    pub class_id: Option<f64>,
    pub team: Option<f64>,
    pub building: f64,
    pub position: Option<[f64; 3]>,
    pub velocity: Option<[f64; 3]>,
    pub quaternion: Option<[f64; 4]>,
    pub yaw: Option<f64>,
    pub pitch: Option<f64>,
    pub health: Option<f64>,
    pub posture: f64,
    pub charge: Option<f64>,
    pub state: WireRecordState,
    pub weapon: f64,
    pub fire_counter: Option<f64>,
    pub power: f64,
    pub mode: f64,
    pub reverse: bool,
    pub dead: bool,
    pub shield_on: bool,
    pub time: f64,
    pub roll: f64,
    pub lean: f64,
    pub legs: f64,
    pub shield: f64,
    pub gun_yaw: f64,
    pub gun_pitch: f64,
    pub active: bool,
    pub definition_id: Option<f64>,
    pub up: Option<[f64; 3]>,
    pub slot: Option<f64>,
    pub tilt: f64,
    pub walk_phase: f64,
    pub walk_blend: f64,
    pub seats: Option<Vec<WireSeatAngles>>,
    pub vehicle_id: Option<f64>,
    pub seat_index: Option<f64>,
}

impl WireRecord {
    pub const WORDS: usize = 66;

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 66] = (&mut row[..66]).try_into().unwrap();
        row[0] = self.kind as u8 as f64;
        row[1] = self.id;
        row[2] = self.generation;
        match &self.class_id { Some(v) => { row[3] = 0.0; row[3 + 1] = (*v); } None => { row[3] = 1.0; row[3 + 1..3 + 2].fill(0.0); } }
        match &self.team { Some(v) => { row[5] = 0.0; row[5 + 1] = (*v); } None => { row[5] = 1.0; row[5 + 1..5 + 2].fill(0.0); } }
        row[7] = self.building;
        match &self.position { Some(v) => { row[8] = 0.0; row[8 + 1..8 + 1 + 3].copy_from_slice(&(*v)); } None => { row[8] = 1.0; row[8 + 1..8 + 4].fill(0.0); } }
        match &self.velocity { Some(v) => { row[12] = 0.0; row[12 + 1..12 + 1 + 3].copy_from_slice(&(*v)); } None => { row[12] = 1.0; row[12 + 1..12 + 4].fill(0.0); } }
        match &self.quaternion { Some(v) => { row[16] = 0.0; row[16 + 1..16 + 1 + 4].copy_from_slice(&(*v)); } None => { row[16] = 1.0; row[16 + 1..16 + 5].fill(0.0); } }
        match &self.yaw { Some(v) => { row[21] = 0.0; row[21 + 1] = (*v); } None => { row[21] = 1.0; row[21 + 1..21 + 2].fill(0.0); } }
        match &self.pitch { Some(v) => { row[23] = 0.0; row[23 + 1] = (*v); } None => { row[23] = 1.0; row[23 + 1..23 + 2].fill(0.0); } }
        match &self.health { Some(v) => { row[25] = 0.0; row[25 + 1] = (*v); } None => { row[25] = 1.0; row[25 + 1..25 + 2].fill(0.0); } }
        row[27] = self.posture;
        match &self.charge { Some(v) => { row[28] = 0.0; row[28 + 1] = (*v); } None => { row[28] = 1.0; row[28 + 1..28 + 2].fill(0.0); } }
        self.state.put(&mut row[30..30 + 2], heap);
        row[32] = self.weapon;
        match &self.fire_counter { Some(v) => { row[33] = 0.0; row[33 + 1] = (*v); } None => { row[33] = 1.0; row[33 + 1..33 + 2].fill(0.0); } }
        row[35] = self.power;
        row[36] = self.mode;
        row[37] = if self.reverse { 1.0 } else { 0.0 };
        row[38] = if self.dead { 1.0 } else { 0.0 };
        row[39] = if self.shield_on { 1.0 } else { 0.0 };
        row[40] = self.time;
        row[41] = self.roll;
        row[42] = self.lean;
        row[43] = self.legs;
        row[44] = self.shield;
        row[45] = self.gun_yaw;
        row[46] = self.gun_pitch;
        row[47] = if self.active { 1.0 } else { 0.0 };
        match &self.definition_id { Some(v) => { row[48] = 0.0; row[48 + 1] = (*v); } None => { row[48] = 1.0; row[48 + 1..48 + 2].fill(0.0); } }
        match &self.up { Some(v) => { row[50] = 0.0; row[50 + 1..50 + 1 + 3].copy_from_slice(&(*v)); } None => { row[50] = 1.0; row[50 + 1..50 + 4].fill(0.0); } }
        match &self.slot { Some(v) => { row[54] = 0.0; row[54 + 1] = (*v); } None => { row[54] = 1.0; row[54 + 1..54 + 2].fill(0.0); } }
        row[56] = self.tilt;
        row[57] = self.walk_phase;
        row[58] = self.walk_blend;
        match &self.seats { Some(v) => { row[59] = 0.0; { let at = heap.len(); row[59 + 1] = at as f64; row[59 + 1 + 1] = v.len() as f64; heap.resize(at + v.len() * 2, 0.0); for (i, e) in v.iter().enumerate() { let mut item = [0.0f64; 2]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 2..at + (i + 1) * 2].copy_from_slice(&item); } } } None => { row[59] = 1.0; row[59 + 1..59 + 3].fill(0.0); } }
        match &self.vehicle_id { Some(v) => { row[62] = 0.0; row[62 + 1] = (*v); } None => { row[62] = 1.0; row[62 + 1..62 + 2].fill(0.0); } }
        match &self.seat_index { Some(v) => { row[64] = 0.0; row[64 + 1] = (*v); } None => { row[64] = 1.0; row[64 + 1..64 + 2].fill(0.0); } }
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 66] = (&row[..66]).try_into().unwrap();
        Self {
            kind: WireRecordKind::from_u8(word_u32(row[0]) as u8).unwrap_or_default(),
            id: row[1],
            generation: row[2],
            class_id: if row[3] == 0.0 { Some(row[3 + 1]) } else { None },
            team: if row[5] == 0.0 { Some(row[5 + 1]) } else { None },
            building: row[7],
            position: if row[8] == 0.0 { Some({ let mut a = [0.0; 3]; a.copy_from_slice(&row[8 + 1..8 + 1 + 3]); a }) } else { None },
            velocity: if row[12] == 0.0 { Some({ let mut a = [0.0; 3]; a.copy_from_slice(&row[12 + 1..12 + 1 + 3]); a }) } else { None },
            quaternion: if row[16] == 0.0 { Some({ let mut a = [0.0; 4]; a.copy_from_slice(&row[16 + 1..16 + 1 + 4]); a }) } else { None },
            yaw: if row[21] == 0.0 { Some(row[21 + 1]) } else { None },
            pitch: if row[23] == 0.0 { Some(row[23 + 1]) } else { None },
            health: if row[25] == 0.0 { Some(row[25 + 1]) } else { None },
            posture: row[27],
            charge: if row[28] == 0.0 { Some(row[28 + 1]) } else { None },
            state: WireRecordState::take(&row[30..30 + 2], heap),
            weapon: row[32],
            fire_counter: if row[33] == 0.0 { Some(row[33 + 1]) } else { None },
            power: row[35],
            mode: row[36],
            reverse: row[37] != 0.0,
            dead: row[38] != 0.0,
            shield_on: row[39] != 0.0,
            time: row[40],
            roll: row[41],
            lean: row[42],
            legs: row[43],
            shield: row[44],
            gun_yaw: row[45],
            gun_pitch: row[46],
            active: row[47] != 0.0,
            definition_id: if row[48] == 0.0 { Some(row[48 + 1]) } else { None },
            up: if row[50] == 0.0 { Some({ let mut a = [0.0; 3]; a.copy_from_slice(&row[50 + 1..50 + 1 + 3]); a }) } else { None },
            slot: if row[54] == 0.0 { Some(row[54 + 1]) } else { None },
            tilt: row[56],
            walk_phase: row[57],
            walk_blend: row[58],
            seats: if row[59] == 0.0 { Some({ let (at, n) = (word_u32(row[59 + 1]) as usize, word_u32(row[59 + 1 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 2..at + (i + 1) * 2]; out.push(WireSeatAngles::take(&row[0..], heap)); } out }) } else { None },
            vehicle_id: if row[62] == 0.0 { Some(row[62 + 1]) } else { None },
            seat_index: if row[64] == 0.0 { Some(row[64 + 1]) } else { None },
        }
    }

}

#[derive(Clone, Debug, Default, PartialEq)]
pub struct WireCapture {
    pub tick: f64,
    pub epoch: f64,
    pub records: Vec<WireRecord>,
    pub world: Vec<WireField>,
    pub bounds: WireBounds,
}

impl WireCapture {
    pub const WORDS: usize = 12;

    pub fn put(&self, row: &mut [f64], heap: &mut Vec<f64>) {
        let row: &mut [f64; 12] = (&mut row[..12]).try_into().unwrap();
        row[0] = self.tick;
        row[1] = self.epoch;
        { let at = heap.len(); row[2] = at as f64; row[2 + 1] = self.records.len() as f64; heap.resize(at + self.records.len() * 66, 0.0); for (i, e) in self.records.iter().enumerate() { let mut item = [0.0f64; 66]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 66..at + (i + 1) * 66].copy_from_slice(&item); } }
        { let at = heap.len(); row[4] = at as f64; row[4 + 1] = self.world.len() as f64; heap.resize(at + self.world.len() * 5, 0.0); for (i, e) in self.world.iter().enumerate() { let mut item = [0.0f64; 5]; { let row = &mut item; e.put(&mut row[0..], heap); } heap[at + i * 5..at + (i + 1) * 5].copy_from_slice(&item); } }
        self.bounds.put(&mut row[6..], heap);
    }

    pub fn take(row: &[f64], heap: &[f64]) -> Self {
        let row: &[f64; 12] = (&row[..12]).try_into().unwrap();
        Self {
            tick: row[0],
            epoch: row[1],
            records: { let (at, n) = (word_u32(row[2]) as usize, word_u32(row[2 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 66..at + (i + 1) * 66]; out.push(WireRecord::take(&row[0..], heap)); } out },
            world: { let (at, n) = (word_u32(row[4]) as usize, word_u32(row[4 + 1]) as usize); let mut out = Vec::with_capacity(n); for i in 0..n { let row = &heap[at + i * 5..at + (i + 1) * 5]; out.push(WireField::take(&row[0..], heap)); } out },
            bounds: WireBounds::take(&row[6..], heap),
        }
    }

}
